function buildRobots(groups){
  var lines = [];
  (groups || []).forEach(function(g){
    lines.push("User-agent: " + (g.ua || "*"));
    (g.allow || []).forEach(function(a){ if (a && a.trim()) lines.push("Allow: " + a.trim()); });
    (g.disallow || []).forEach(function(d){ if (d && d.trim()) lines.push("Disallow: " + d.trim()); });
    if (g.crawlDelay != null && g.crawlDelay !== "" && !isNaN(g.crawlDelay)) lines.push("Crawl-delay: " + g.crawlDelay);
    if (g.sitemap) lines.push("Sitemap: " + g.sitemap);
    lines.push("");
  });
  return lines.join("\n").replace(/\n+$/, "\n");
}
var EXPORTS = { buildRobots: buildRobots };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RobotsForgePure = EXPORTS; }
